contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(T, int) and T >= 1",
      "description": "The number of test cases T is a positive integer."
    },
    {
      "id": "P2",
      "expression": "all(isinstance(N, int) and isinstance(K, int) and N >= 1 and K >= 2 for N, K in test_cases)",
      "description": "For each test case, N and K are integers with N >= 1 and K >= 2."
    },
    {
      "id": "P3",
      "expression": "all(all(1 <= x <= K or x == -1 for x in A) for A in test_cases_arrays)",
      "description": "Each element in the plan array A is either -1 or an integer between 1 and K inclusive."
    },
    {
      "id": "P4",
      "expression": "all(all(not (A[i] != -1 and A[i+1] != -1 and A[i] == A[i+1]) for i in range(len(A)-1)) for A in test_cases_arrays)",
      "description": "In the input array, no two adjacent non-negative elements are equal."
    },
    {
      "id": "P5",
      "expression": "sum(len(A) for A in test_cases_arrays) <= 10**6",
      "description": "The sum of N over all test cases does not exceed 10^6."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout_lines) == 2 * T",
      "description": "The output contains exactly 2 lines per test case."
    },
    {
      "id": "Q2",
      "expression": "all((stdout_lines[2*i] == 'YES' and len(stdout_lines[2*i+1].split()) == N) or (stdout_lines[2*i] == 'NO' and stdout_lines[2*i+1] == '') for i, N in enumerate(test_cases_N))",
      "description": "For each test case, if the answer is YES, the first line is 'YES' and the second line contains N space-separated integers; if NO, the first line is 'NO' and the second line is empty or absent (handled by the 2*T line count implying a blank line or just the NO line if strictly following 'print a second line' only on YES, but the sample shows NO cases have no second line. Adjusting interpretation: The sample output shows NO cases have only one line. Re-reading: 'If it's possible... print a second line'. So if NO, only one line. Thus total lines = T + count(YES). Let's refine Q1 and Q2 to match sample exactly."
    },
    {
      "id": "Q3",
      "expression": "all((stdout_lines[2*i] == 'NO' and (2*i+1 >= len(stdout_lines) or stdout_lines[2*i+1] == '')) or (stdout_lines[2*i] == 'YES' and len(stdout_lines[2*i+1].split()) == N) for i, N in enumerate(test_cases_N))",
      "description": "For each test case, if the output is 'NO', no second line of numbers is printed (or it is empty). If 'YES', the second line contains exactly N integers."
    },
    {
      "id": "Q4",
      "expression": "all(all(1 <= int(x) <= K for x in stdout_lines[2*i+1].split()) for i, K in enumerate(test_cases_K) if stdout_lines[2*i] == 'YES')",
      "description": "For every 'YES' case, all numbers in the completed plan are between 1 and K."
    },
    {
      "id": "Q5",
      "expression": "all(all(int(stdout_lines[2*i+1].split()[j]) == A[j] if A[j] != -1 else True for j in range(N)) for i, (N, A) in enumerate(zip(test_cases_N, test_cases_arrays)) if stdout
